begin;
create extension if not exists pgtap with schema extensions;
select plan(25);
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000080','chat-owner@test.invalid'),('10000000-0000-4000-8000-000000000081','chat-reader@test.invalid'),('10000000-0000-4000-8000-000000000082','chat-outsider@test.invalid');
insert into public.workspaces(id,name) values ('20000000-0000-4000-8000-000000000080','Chat test'),('20000000-0000-4000-8000-000000000081','Other chat workspace');
insert into public.workspace_members(workspace_id,user_id,role) values ('20000000-0000-4000-8000-000000000080','10000000-0000-4000-8000-000000000080','owner'),('20000000-0000-4000-8000-000000000080','10000000-0000-4000-8000-000000000081','member');
select set_config('test.request','{"template":"product_delivery","version":1,"objective":"Release","context":"Small team","hardConstraints":[{"kind":"prohibition","text":"No downtime"}],"conceptIds":[],"unknowns":""}',true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000080","role":"authenticated"}',true);
select is(public.create_conversation('20000000-0000-4000-8000-000000000080','30000000-0000-4000-8000-000000000080'),'30000000-0000-4000-8000-000000000080'::uuid,'conversation created');
select is(public.create_conversation('20000000-0000-4000-8000-000000000080','30000000-0000-4000-8000-000000000080'),'30000000-0000-4000-8000-000000000080'::uuid,'conversation create idempotent');
select throws_ok($$select public.create_conversation('20000000-0000-4000-8000-000000000081',gen_random_uuid())$$,'42501',null,'forged workspace denied');
select throws_ok($$select public.save_conversation_turn('30000000-0000-4000-8000-000000000080',gen_random_uuid(),'Question','{}')$$,'23514',null,'direct RPC invalid snapshot rejected');
select set_config('test.turn',public.save_conversation_turn('30000000-0000-4000-8000-000000000080','40000000-0000-4000-8000-000000000080','How can we release?',current_setting('test.request')::jsonb)::text,true);
select is((select count(*) from public.conversation_turns),1::bigint,'turn persisted without model or run');
select is((select count(*) from public.analysis_runs where conversation_turn_id=current_setting('test.turn')::uuid),0::bigint,'saved turn does not claim generation started');
select is(public.save_conversation_turn('30000000-0000-4000-8000-000000000080','40000000-0000-4000-8000-000000000080','How can we release?',current_setting('test.request')::jsonb),current_setting('test.turn')::uuid,'replayed turn returns original');
select throws_ok($$select public.save_conversation_turn('30000000-0000-4000-8000-000000000080','40000000-0000-4000-8000-000000000080','Different question',current_setting('test.request')::jsonb)$$,'23505',null,'key cannot overwrite a turn');
select throws_ok($$select public.save_conversation_turn('30000000-0000-4000-8000-000000000080',gen_random_uuid(),'Stale question',current_setting('test.request')::jsonb)$$,'23505',null,'stale parent denied');
select is(public.admit_conversation_analysis(current_setting('test.turn')::uuid,'50000000-0000-4000-8000-000000000080',2,90000)->>'kind','admitted','turn admits through shared engine policy');
select is((select request from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000080'),current_setting('test.request')::jsonb,'run uses persisted snapshot');
select is(public.admit_conversation_analysis(current_setting('test.turn')::uuid,'50000000-0000-4000-8000-000000000080',2,90000)->>'kind','duplicate','attempt replay does not create another run');
select is(public.admit_conversation_analysis(current_setting('test.turn')::uuid,gen_random_uuid(),2,90000)->>'kind','quota','one active run per conversation');
select throws_ok($$select public.save_conversation_turn('30000000-0000-4000-8000-000000000080',gen_random_uuid(),'During run',current_setting('test.request')::jsonb,current_setting('test.turn')::uuid)$$,'23505',null,'cannot append during active run');
select public.finish_analysis((select id from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000080'),'failed',null,'[]','MODEL_UNAVAILABLE',null);
select is(public.admit_conversation_analysis(current_setting('test.turn')::uuid,'50000000-0000-4000-8000-000000000081',2,90000)->>'kind','admitted','terminal failure can retry as a new attempt');
select public.finish_analysis((select id from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000081'),'gap_report',null,'[]',null,null);
select throws_ok($$select public.admit_conversation_analysis(current_setting('test.turn')::uuid,gen_random_uuid(),2,90000)$$,'23505',null,'answered turn cannot be rerun');
select set_config('test.next',public.save_conversation_turn('30000000-0000-4000-8000-000000000080','40000000-0000-4000-8000-000000000081','What if only one operator?',current_setting('test.request')::jsonb,current_setting('test.turn')::uuid)::text,true);
select is((select position from public.conversation_turns where id=current_setting('test.next')::uuid),2,'follow-up keeps ordered history');
select throws_ok($$select public.admit_conversation_analysis(current_setting('test.turn')::uuid,gen_random_uuid(),2,90000)$$,'23505',null,'cannot run an older turn after follow-up');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000081","role":"authenticated"}',true);
select is((select count(*) from public.conversation_turns),2::bigint,'workspace member can read history');
select throws_ok($$select public.save_conversation_turn('30000000-0000-4000-8000-000000000080',gen_random_uuid(),'Another author',current_setting('test.request')::jsonb,current_setting('test.next')::uuid)$$,'42501',null,'another member cannot append');
select throws_ok($$select public.admit_conversation_analysis(current_setting('test.next')::uuid,gen_random_uuid(),2,90000)$$,'42501',null,'another member cannot execute');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000082","role":"authenticated"}',true);
select is((select count(*) from public.conversations),0::bigint,'nonmember cannot read conversations');
select is((select count(*) from public.conversation_turns),0::bigint,'nonmember cannot read snapshots');
reset role;
select throws_ok($$update public.conversation_turns set message='Overwrite' where id=current_setting('test.turn')::uuid$$,'23514',null,'turns immutable even through privileged writes');
select throws_ok($$insert into public.analysis_runs(workspace_id,author_id,request_key,request,knowledge_version,deadline_at,conversation_turn_id) values('20000000-0000-4000-8000-000000000081','10000000-0000-4000-8000-000000000080',gen_random_uuid(),current_setting('test.request')::jsonb,0,now()+interval '1 minute',current_setting('test.turn')::uuid)$$,'23503',null,'run cannot link a turn across workspaces');
select * from finish();
rollback;
